#[test]
fn fixes_from_1456_match_vanilla() {
    for &(ty, from, to, input, expected) in CASES_FROM_1456 {
        assert_eq!(update(ty, from, to, input), expected, "{ty} {from} -> {to}: {input}");
    }
}

#[test]
#[should_panic(expected = "Index 16 out of bounds for length 16")]
fn legacy_tile_ticks_above_the_world_panic_like_vanilla() {
    update("chunk", 1465, 1466, r##"{Level:{xPos:0,zPos:0,TileTicks:[{i:"minecraft:stone",p:0,t:10,x:1,y:256,z:3}]}}"##);
}

#[test]
#[should_panic(expected = "Index -1 out of bounds for length 16")]
fn legacy_tile_ticks_below_the_world_panic_like_vanilla() {
    update("chunk", 1465, 1466, r##"{Level:{xPos:0,zPos:0,TileTicks:[{i:"minecraft:stone",p:0,t:10,x:1,y:-1,z:3}]}}"##);
}

#[test]
#[should_panic(expected = "Invalid length given for storage, got: 0 but expected: 256")]
fn sections_without_block_states_panic_in_the_leaves_fix_like_vanilla() {
    update("chunk", 1495, 1496, r##"{Level:{xPos:0,zPos:0,Sections:[{Y:0b,Palette:[{Name:"minecraft:oak_log"}]}]}}"##);
}

